SET SERVEROUTPUT ON
DECLARE
  n     NUMBER := 5274;
  t     NUMBER;
  d     NUMBER;
  v_rev NUMBER := 0;
  v_sum NUMBER := 0;
BEGIN
  t := n;
  WHILE t > 0 LOOP
    d := MOD(t, 10);
    v_rev := v_rev * 10 + d;
    v_sum := v_sum + d;
    t := TRUNC(t / 10);
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Number  : ' || n);
  DBMS_OUTPUT.PUT_LINE('Reverse : '
    || v_rev);
  DBMS_OUTPUT.PUT_LINE('Sum     : '
    || v_sum);
  IF v_rev = n THEN
    DBMS_OUTPUT.PUT_LINE('Palindrome');
  ELSE
    DBMS_OUTPUT.PUT_LINE('Not palindrome');
  END IF;
END;
/

SET SERVEROUTPUT ON
DECLARE
  n      NUMBER := 6;
  v_fact NUMBER := 1;
BEGIN
  FOR i IN 1..n LOOP
    v_fact := v_fact * i;
  END LOOP;
  DBMS_OUTPUT.PUT_LINE('Factorial of '
    || n || ' = ' || v_fact);

  FOR i IN REVERSE 1..5 LOOP
    DBMS_OUTPUT.PUT(i || ' ');
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;

  FOR i IN 1..20 LOOP
    IF MOD(i, 3) = 0 THEN
      DBMS_OUTPUT.PUT(i || ' ');
    END IF;
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
END;
/

SET SERVEROUTPUT ON
DECLARE
  v_prime BOOLEAN;
  v_count NUMBER := 0;
BEGIN
  FOR n IN 2..30 LOOP
    v_prime := TRUE;
    FOR d IN 2..TRUNC(SQRT(n)) LOOP
      IF MOD(n, d) = 0 THEN
        v_prime := FALSE;
        EXIT;
      END IF;
    END LOOP;
    IF v_prime THEN
      DBMS_OUTPUT.PUT(n || ' ');
      v_count := v_count + 1;
    END IF;
  END LOOP;
  DBMS_OUTPUT.NEW_LINE;
  DBMS_OUTPUT.PUT_LINE('Total primes: '
    || v_count);
END;
/

