DECLARE
  e_low_bal EXCEPTION;
  e_bad_amt EXCEPTION;
  v_bal account.balance%TYPE;
  v_amt NUMBER;
BEGIN
  FOR i IN 1..3 LOOP
    v_amt := CASE i WHEN 1 THEN 2000
             WHEN 2 THEN 7000 ELSE -50 END;
    BEGIN
      IF v_amt <= 0 THEN
        RAISE e_bad_amt;
      END IF;
      SELECT balance INTO v_bal
      FROM account WHERE acc_no = 1;
      IF v_amt > v_bal THEN
        RAISE e_low_bal;
      END IF;
      UPDATE account
      SET balance = balance - v_amt
      WHERE acc_no = 1;
      DBMS_OUTPUT.PUT_LINE('Withdrawn '
        || v_amt || ', balance '
        || (v_bal - v_amt));
    EXCEPTION
      WHEN e_low_bal THEN
        DBMS_OUTPUT.PUT_LINE(v_amt
          || ': insufficient balance');
      WHEN e_bad_amt THEN
        DBMS_OUTPUT.PUT_LINE(v_amt
          || ': invalid amount');
    END;
  END LOOP;
END;
